import{_ as s,o as n,c as m,aN as t}from"./chunks/framework.D31DlcCL.js";const l="/img/math-diff-multiple-adv.svg",g=JSON.parse('{"title":"小学奥数进阶：差倍问题的高效解法","description":"已知差与倍数，如何快速求解？本文深入探讨差倍问题的进阶模型，包括隐藏差、变化倍数等高难度题型。","frontmatter":{"title":"小学奥数进阶：差倍问题的高效解法","date":"2026-02-08T09:20:00.000Z","categories":["数学"],"tags":["小学数学","奥数","差倍问题"],"description":"已知差与倍数，如何快速求解？本文深入探讨差倍问题的进阶模型，包括隐藏差、变化倍数等高难度题型。","cover":"/img/math-diff-multiple-adv.svg","top_img":"/img/banner.svg","toc_number":true,"katex":true},"headers":[],"relativePath":"posts/primary-math-olympiad-diff-multiple-adv.md","filePath":"posts/primary-math-olympiad-diff-multiple-adv.md","lastUpdated":null}'),p={name:"posts/primary-math-olympiad-diff-multiple-adv.md"};function r(o,a,e,i,c,h){return n(),m("div",null,[...a[0]||(a[0]=[t('<h1 id="小学奥数进阶-差倍问题的高效解法" tabindex="-1">小学奥数进阶：差倍问题的高效解法 <a class="header-anchor" href="#小学奥数进阶-差倍问题的高效解法" aria-label="Permalink to &quot;小学奥数进阶：差倍问题的高效解法&quot;">​</a></h1><h2 id="一、-核心模型回顾" tabindex="-1">一、 核心模型回顾 <a class="header-anchor" href="#一、-核心模型回顾" aria-label="Permalink to &quot;一、 核心模型回顾&quot;">​</a></h2><p>已知两个数的<strong>差</strong>以及它们的<strong>倍数关系</strong>，求这两个数。</p><ul><li><strong>小数（1份量）= 差 ÷ (倍数 - 1)</strong></li><li><strong>大数 = 小数 × 倍数</strong></li></ul><h3 id="图解逻辑" tabindex="-1">图解逻辑 <a class="header-anchor" href="#图解逻辑" aria-label="Permalink to &quot;图解逻辑&quot;">​</a></h3><p><img src="'+l+'" alt="差倍问题进阶图解"></p><p>大数比小数多出的“倍数 - 1”份，对应的正是题目中的“差”。</p><hr><h2 id="二、-进阶变式-复杂的数量关系" tabindex="-1">二、 进阶变式：复杂的数量关系 <a class="header-anchor" href="#二、-进阶变式-复杂的数量关系" aria-label="Permalink to &quot;二、 进阶变式：复杂的数量关系&quot;">​</a></h2><h3 id="_1-隐藏的-差" tabindex="-1">1. 隐藏的“差” <a class="header-anchor" href="#_1-隐藏的-差" aria-label="Permalink to &quot;1. 隐藏的“差”&quot;">​</a></h3><p><strong>例题</strong>：甲仓库粮食是乙仓库的 3 倍。如果从甲仓库运出 20 吨放入乙仓库，两个仓库的粮食就一样多了。原来两个仓库各有多少吨？</p><p><strong>解析</strong>：</p><ul><li><strong>找倍数</strong>：倍数 = 3。</li><li><strong>找差</strong>：甲给乙 20 吨后相等，说明甲原来比乙多 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>2</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 2 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span> 吨。即 <strong>差 = 40</strong>。</li><li><strong>计算</strong>： <ul><li><strong>乙（1份量）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>0</mn><mo>÷</mo><mo>(</mo><mn>3</mn><mo>−</mo><mn>1</mn><mo>)</mo><mo>=</mo><mn>2</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">40 \\div (3 - 1) = 20</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">0</span><span class="mbin">÷</span><span class="mopen">(</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">1</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span></span></span></span>（吨）。</li><li><strong>甲</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>6</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 \\times 3 = 60</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">6</span><span class="mord mathrm">0</span></span></span></span>（吨）。</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>0</mn><mo>−</mo><mn>2</mn><mn>0</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">60 - 20 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>；<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>0</mn><mo>−</mo><mn>2</mn><mn>0</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">60 - 20 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">0</span><span class="mbin">−</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>0</mn><mo>+</mo><mn>2</mn><mn>0</mn><mo>=</mo><mn>4</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">20 + 20 = 40</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">2</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">4</span><span class="mord mathrm">0</span></span></span></span>，相等！</li></ul><h3 id="_2-多几-或-少几-的差倍问题" tabindex="-1">2. “多几”或“少几”的差倍问题 <a class="header-anchor" href="#_2-多几-或-少几-的差倍问题" aria-label="Permalink to &quot;2. “多几”或“少几”的差倍问题&quot;">​</a></h3><p><strong>例题</strong>：甲数比乙数的 4 倍多 5。已知甲数比乙数多 26。求甲乙两数。</p><p><strong>解析</strong>：</p><ul><li><strong>画图思维</strong>： <ul><li>乙是 1 份。</li><li>甲是 4 份 + 5。</li><li>甲 - 乙 = (4 份 + 5) - 1 份 = 3 份 + 5。</li></ul></li><li><strong>对应关系</strong>： <ul><li>题目说甲比乙多 26，所以 3份 + 5 = 26。</li></ul></li><li><strong>计算</strong>： <ul><li>3份 = 26 - 5 = 21。</li><li><strong>乙（1份量）</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>1</mn><mo>÷</mo><mn>3</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">21 \\div 3 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">1</span><span class="mbin">÷</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span>。</li><li><strong>甲</strong> = <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mo>×</mo><mn>4</mn><mo>+</mo><mn>5</mn><mo>=</mo><mn>3</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">7 \\times 4 + 5 = 33</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">4</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">3</span></span></span></span>。</li></ul></li><li><strong>验证</strong>：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>3</mn><mn>3</mn><mo>−</mo><mn>7</mn><mo>=</mo><mn>2</mn><mn>6</mn></mrow><annotation encoding="application/x-tex">33 - 7 = 26</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">3</span><span class="mord mathrm">3</span><span class="mbin">−</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">2</span><span class="mord mathrm">6</span></span></span></span>，正确！</li></ul><hr><h2 id="三、-解题技巧总结" tabindex="-1">三、 解题技巧总结 <a class="header-anchor" href="#三、-解题技巧总结" aria-label="Permalink to &quot;三、 解题技巧总结&quot;">​</a></h2><ol><li><strong>核心公式</strong>：记住分母是 <strong>(倍数 - 1)</strong>，因为差对应的是份数之差。</li><li><strong>处理偏差</strong>： <ul><li>如果是“n 倍多几”，差里面要<strong>减去</strong>这个多出的部分。</li><li>如果是“n 倍少几”，差里面要<strong>加上</strong>这个缺少的部分。</li></ul></li><li><strong>线段图</strong>：永远是分析数量关系最可靠的工具。</li></ol><hr><h2 id="四、-举一反三-练习题" tabindex="-1">四、 举一反三（练习题） <a class="header-anchor" href="#四、-举一反三-练习题" aria-label="Permalink to &quot;四、 举一反三（练习题）&quot;">​</a></h2><ol><li>小明今年的年龄是小红的 5 倍，小明比小红大 12 岁。小明和小红今年各几岁？</li><li>两个仓库原来存粮一样多。如果从甲仓运出 8 吨，乙仓运进 12 吨，此时乙仓的粮食是甲仓的 3 倍。原来两个仓库各存粮多少吨？</li></ol><hr><p><em>关键点：找准 1 份量，算对份数差！</em></p>',25)])])}const u=s(p,[["render",r]]);export{g as __pageData,u as default};
